def icon_image(size=256):
    """The logo as a PIL image, scaled smoothly to `size` pixels."""
    from PIL import Image
    im = Image.open(io.BytesIO(base64.b64decode(_PNG_B64))).convert("RGBA")
    if size != im.width:
        im = im.resize((size, size), Image.LANCZOS)
    return im


def write_ico(path):
    """Write a multi-size Windows icon file."""
    sizes = [16, 24, 32, 48, 64, 128, 256]
    icon_image(256).save(path, sizes=[(s, s) for s in sizes])
